<template>
  <div class="user-management">
    <section class="user-metrics"><article class="user-metric-card"><span class="user-metric-icon user-tone-green">♙</span><div><small>总用户数</small><strong>24,680</strong><em>较上月增长 8.6%</em></div></article><article class="user-metric-card"><span class="user-metric-icon user-tone-blue">＋</span><div><small>新增用户数</small><strong>1,286</strong><em>本月新增注册用户</em></div></article></section>
    <section class="admin-card user-list-card"><div class="user-list-head"><div><span class="admin-eyebrow">USER DIRECTORY</span><h2>用户信息</h2><p>查看用户资料、会员等级、订单数量和账号状态。</p></div><button class="admin-primary" @click="notify('已打开新增用户弹窗')">＋ 新增用户</button></div><div class="user-toolbar"><div class="search-admin user-search">⌕ <input v-model.trim="keyword" placeholder="搜索用户姓名、手机号、用户编号..." /></div><select v-model="levelFilter"><option value="全部等级">全部等级</option><option v-for="level in levels" :key="level" :value="level">{{ level }}</option></select><select v-model="statusFilter"><option value="全部状态">全部状态</option><option value="正常">正常</option><option value="已禁用">已禁用</option></select></div><div class="data-summary"><span>共 {{ filteredUsers.length }} 条用户记录</span><span>最后更新：刚刚</span></div><div class="user-table-wrap"><table class="user-table"><thead><tr><th>用户信息</th><th>注册时间</th><th>会员等级</th><th>订单数</th><th>累计消费</th><th>最近登录</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="user in filteredUsers" :key="user.id"><td><div class="user-identity"><span class="user-avatar">{{ user.name.slice(0, 1) }}</span><div><b>{{ user.name }}</b><small>{{ user.id }} · {{ user.phone }}</small></div></div></td><td>{{ user.joinedAt }}</td><td><span class="user-level" :class="user.levelClass">{{ user.level }}</span></td><td>{{ user.orders }} 单</td><td class="user-spend">¥{{ user.spend.toLocaleString('zh-CN', { minimumFractionDigits: 2 }) }}</td><td>{{ user.lastLogin }}</td><td><span class="user-status" :class="user.status === '正常' ? 'is-active' : 'is-disabled'">{{ user.status }}</span></td><td><button class="table-action" @click="notify(`已打开“${user.name}”用户详情`)">查看详情</button></td></tr><tr v-if="!filteredUsers.length"><td colspan="8" class="user-empty">没有找到符合条件的用户</td></tr></tbody></table></div><div class="pagination"><button disabled>‹</button><span class="active">1</span><button>2</button><button>3</button><span>…</span><button>›</button></div></section>
  </div>
</template>
<script setup>
import { computed, ref } from 'vue'
const emit = defineEmits(['notify'])
const notify = message => emit('notify', message)
const keyword = ref(''), levelFilter = ref('全部等级'), statusFilter = ref('全部状态')
const levels = ['普通会员', '白银会员', '黄金会员', '钻石会员']
const users = [{ id: 'U10028', name: '林女士', phone: '138****2088', joinedAt: '2026-03-12', level: '黄金会员', levelClass: 'level-gold', orders: 28, spend: 2680.5, lastLogin: '今天 10:18', status: '正常' }, { id: 'U10029', name: '王先生', phone: '139****3812', joinedAt: '2026-04-08', level: '普通会员', levelClass: 'level-normal', orders: 12, spend: 986.8, lastLogin: '今天 09:42', status: '正常' }, { id: 'U10030', name: '陈女士', phone: '137****6621', joinedAt: '2026-05-21', level: '白银会员', levelClass: 'level-silver', orders: 19, spend: 1428.2, lastLogin: '昨天 18:06', status: '正常' }, { id: 'U10031', name: '赵先生', phone: '136****7190', joinedAt: '2026-01-17', level: '钻石会员', levelClass: 'level-diamond', orders: 43, spend: 5688, lastLogin: '今天 08:55', status: '正常' }, { id: 'U10032', name: '周女士', phone: '158****9203', joinedAt: '2026-06-03', level: '黄金会员', levelClass: 'level-gold', orders: 24, spend: 2180.9, lastLogin: '2026-10-21', status: '正常' }, { id: 'U10033', name: '刘先生', phone: '186****4028', joinedAt: '2026-07-19', level: '普通会员', levelClass: 'level-normal', orders: 4, spend: 326, lastLogin: '2026-09-28', status: '已禁用' }]
const filteredUsers = computed(() => { const query = keyword.value.toLowerCase(); return users.filter(user => (!query || [user.id, user.name, user.phone, user.level].some(value => value.toLowerCase().includes(query))) && (levelFilter.value === '全部等级' || user.level === levelFilter.value) && (statusFilter.value === '全部状态' || user.status === statusFilter.value)) })
</script>
